# Combine all data
all_data = v2_data + new_examples

# Remove duplicates (keep last occurrence)
seen = set()
unique_data = []
for item in reversed(all_data):
    key = item["instruction"].lower().strip()
    if key not in seen:
        seen.add(key)
        unique_data.append(item)
unique_data.reverse()

# Write v3
with open("harz_training_data_v3.jsonl", "w") as f:
    for item in unique_data:
        f.write(json.dumps(item) + "\n")

print(f"v2 data: {len(v2_data)}")
print(f"New examples: {len(new_examples)}")
print(f"After dedup: {len(unique_data)}")
print(f"Total v3: {len(unique_data)} examples")
print("Saved to harz_training_data_v3.jsonl")
